Change(genesis='e44b01205cdace6f30ebc3c48eee515a5e1ef4d70aae9a18b591ba5f45a131a9', deps=('d30f1bde007ba1f3ea76e1a3ef9c4bea850de4133e6f1dad7e852c9ae1ca3fbc',), event=Authored(todo='mergeable-tag-sets', at=datetime(2026, 10, 17, 10, 4, 41, 250366), actor='maintainer', kind='todo', created=datetime(2026, 10, 17, 10, 4, 41, 250366), body='a register for a mergeable set of tags on any object, with aliases for renames', spec=None, rationale=(), category='', waiting_on='', detail="Applications need to label objects with more than one tag: topics on a conversation's turns, for example. Tags on an object form a set that two replicas merge without conflict (an add and a remove are events, an observed-remove set), and a rename or a merge of two tags is an alias event, so no object is rewritten. A query over tags (one tag, or the intersection of several) reads like any other fold. Price 85: an application can build this itself today, but each one would build it alike.", source=None, subtodos=(), notes=(), note=''))